import assert from 'node:assert/strict';
import fs from 'node:fs/promises';

export async function runMotionStreamPlacementSmoke(page){
 const previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));
 async function ready(){await page.waitForFunction(()=>{const f=document.querySelector('#preview'),d=f?.contentDocument;const g=d?.querySelector('.nw-stream-group'),e=sec().elements.find(e=>e.id===selection[0]);return g&&e&&+g.dataset.w===+e.w&&Math.abs(g.clientHeight-e.h)<2&&d?.querySelectorAll('.nw-stream-card').length===12&&d.querySelector('.nw-story-transform-h.size')?.style.display==='block'&&Array.from(d.querySelectorAll('.nw-stream-card')).every(n=>n.width>10);});}
 async function geometry(gid){return page.$eval('#preview',(f,gid)=>{const d=f.contentDocument,g=d.querySelector('[data-id="'+gid+'"]');f.contentWindow.__NAG_SCROLL_DIRECTOR[gid].set(.35);return{w:g.clientWidth,h:g.clientHeight,bg:f.contentWindow.getComputedStyle(g).backgroundColor,shadow:f.contentWindow.getComputedStyle(g).boxShadow,scene:f.contentWindow.getComputedStyle(g.closest('.sc')).getPropertyValue('--bg').trim(),cards:Array.from(g.querySelectorAll('[data-nw-stream-slot]'),n=>({id:n.dataset.id,x:(parseFloat(n.style.left)+parseFloat(n.style.width)/2)/g.clientWidth,y:(parseFloat(n.style.top)+parseFloat(n.style.height)/2)/g.clientHeight,w:parseFloat(n.style.width)/g.clientWidth,h:parseFloat(n.style.height)/g.clientHeight}))};},gid);}
 try{
  for(const source of ['time','scroll']){
   await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',height:100,bg:'#527467',sdEnabled:false,elements:[]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});
   await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-library-tab="library"]');await page.click('[data-motion-template="showcase-stream"]');
   await page.$eval('[data-motion-stream="backgroundType"]',n=>{n.value='none';n.dispatchEvent(new Event('change',{bubbles:true}));});
   await page.$eval('[data-motion-config="source"]',(n,v)=>{n.value=v;n.dispatchEvent(new Event('change',{bubbles:true}));},source);
   await page.click('[data-motion-insert-group]');const gid=await page.evaluate(()=>{NAGWEB_STORY_TIMELINE_UI.setState({docked:false,minimized:true});return selection[0];});assert.equal(await page.evaluate(id=>sec().elements.find(e=>e.id===id).nwMotionInstance.stream.backgroundType,gid),'none');await ready();
   const start=await geometry(gid),members=await page.evaluate(id=>JSON.stringify(sec().elements.filter(e=>e.parent===id)),gid);assert.equal(start.bg,'rgba(0, 0, 0, 0)');assert.equal(start.shadow,'none');assert.equal(start.scene,'#527467');
   // A real click on a rendered card selects the whole placed composition.
   const cardPoint=await page.$eval('#preview',f=>{const fr=f.getBoundingClientRect(),n=f.contentDocument.querySelector('[data-nw-stream-slot]:nth-child(4)').getBoundingClientRect();return{x:fr.left+(n.left+n.width/2)*fr.width/f.clientWidth,y:fr.top+(n.top+n.height/2)*fr.height/f.clientHeight};});await page.mouse.click(cardPoint.x,cardPoint.y);await page.waitForFunction(id=>selection.length===1&&selection[0]===id,{},gid);
   const {sx,sy,cx,cy}=await page.$eval('#preview',(f,id)=>{const fr=f.getBoundingClientRect(),d=f.contentDocument,h=d.querySelector('.nw-story-transform-h.size').getBoundingClientRect(),g=d.querySelector('[data-id="'+id+'"]').getBoundingClientRect(),zx=fr.width/f.clientWidth,zy=fr.height/f.clientHeight;return{sx:fr.left+(h.left+h.width/2)*zx,sy:fr.top+(h.top+h.height/2)*zy,cx:fr.left+(g.left+g.width/2)*zx,cy:fr.top+(g.top+g.height/2)*zy};},gid);
   await page.mouse.move(sx,sy);await page.mouse.down();await page.mouse.move(cx+(sx-cx)*.65,cy+(sy-cy)*.65,{steps:6});await page.mouse.up();await page.waitForFunction(id=>sec().elements.find(e=>e.id===id).w<65,{},gid);await ready();
   const after=await geometry(gid);assert.ok(after.w<start.w*.7);assert.ok(Math.abs(after.w/start.w-after.h/start.h)<.005,'Width and height shrink together');for(let i=0;i<12;i++)for(const k of ['x','y','w','h'])assert.ok(Math.abs(start.cards[i][k]-after.cards[i][k])<.015,'Ring card '+i+' preserves proportional '+k);assert.equal(await page.evaluate(id=>JSON.stringify(sec().elements.filter(e=>e.parent===id)),gid),members,'Scaling the composition does not edit its image members');
   await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});await (await page.$('#preview')).screenshot({path:'/tmp/nagweb-motion-visuals/stream-placement-'+source+'.png'});const saved=await page.evaluate(()=>JSON.stringify(project));await page.evaluate(id=>{undo();selection=[id];curEl=sec().elements.findIndex(e=>e.id===id);renderPane();syncSelectionToFrame();},gid);await ready();const undone=await geometry(gid);assert.ok(Math.abs(undone.w-start.w)<2);await page.evaluate(id=>{redo();selection=[id];curEl=sec().elements.findIndex(e=>e.id===id);renderPane();syncSelectionToFrame();},gid);await ready();assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved);
   // Cancel restores both dimensions and does not create a history entry.
   const cancelled=await page.$eval('#preview',f=>{const d=f.contentDocument,w=f.contentWindow,g=d.querySelector('.nw-stream-group.sc-sel'),h=d.querySelector('.nw-story-transform-h.size'),r=h.getBoundingClientRect(),x=r.left+7,y=r.top+7,initial=[g.style.width,g.style.height],ev=(t,x,y)=>new w.PointerEvent(t,{bubbles:true,cancelable:true,button:0,clientX:x,clientY:y,pointerId:55});h.dispatchEvent(ev('pointerdown',x,y));w.dispatchEvent(ev('pointermove',x-25,y-25));w.dispatchEvent(ev('pointercancel',x-25,y-25));return{initial,after:[g.style.width,g.style.height]};});assert.deepEqual(cancelled.after,cancelled.initial);assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved);
   await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),gid);assert.equal(await page.$eval('[data-motion-stream="backgroundType"]',n=>n.value),'none');await page.click('[data-motion-close]');
   await page.evaluate(()=>{const f=document.createElement('iframe');f.id='stream-placement-export';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(id=>document.querySelector('#stream-placement-export')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[id],{},gid);assert.equal(await page.$eval('#stream-placement-export',(f,id)=>f.contentWindow.getComputedStyle(f.contentDocument.querySelector('[data-id="'+id+'"]')).backgroundColor,gid),'rgba(0, 0, 0, 0)');await page.evaluate(()=>document.querySelector('#stream-placement-export').remove());
  }
  console.log('Showcase Stream colocado: Sin fondo conserva escena, selección de grupo al clicar una tarjeta, tamaño proporcional por mouse en Loop y Scroll, miembros intactos, cancelación, historial, reapertura y exportación OK');
 }catch(error){await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});await page.screenshot({path:'/tmp/nagweb-motion-visuals/stream-placement-failure.png'}).catch(()=>{});throw error;}finally{await page.mouse.up().catch(()=>{});await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#stream-placement-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);}
}
